insert into public.exercises(id,name,name_ar,equipment,equipment_ar,instructions,instructions_ar,movement) values ('goblet-squat','Goblet squat','سكوات بالدمبل','Dumbbell','دمبل','Hold the weight close to your chest. Sit down between your hips, then stand tall. Choose a comfortable depth.','أمسك الدمبل قريباً من صدرك. انزل بثني الركبتين والوركين ثم قف باعتدال. اختر عمقاً مريحاً.','squat'),
('dumbbell-row','Single-arm row','تجديف بذراع واحدة','Dumbbell and bench','دمبل ومقعد','Support one hand on a stable bench. Pull the weight toward your hip and lower with control. Repeat on both sides.','اسند يدك على مقعد ثابت. اسحب الدمبل نحو وركك وأنزله بتحكم. كرر على الجانبين.','pull'),
('floor-press','Dumbbell floor press','ضغط دمبل على الأرض','Dumbbells and mat','دمبل وحصيرة','Lie on the floor with knees bent. Press the dumbbells up, then lower until your upper arms gently touch the floor.','استلقِ على الأرض مع ثني الركبتين. ادفع الدمبل للأعلى ثم أنزله حتى يلامس أعلى الذراعين الأرض برفق.','push'),
('romanian-deadlift','Romanian deadlift','رفعة رومانية','Dumbbells','دمبل','Keep a soft bend in your knees. Move your hips back with the weights close to your legs, then stand tall.','اثنِ ركبتيك قليلاً. ادفع الوركين للخلف والدمبل قريب من ساقيك، ثم قف باعتدال.','hinge'),
('split-squat','Split squat','سكوات متباعد','Bodyweight or dumbbells','وزن الجسم أو دمبل','Take a split stance. Lower straight down with control and push through the front foot to stand. Repeat both sides.','قف بقدم أمام الأخرى. انزل بتحكم وادفع بالقدم الأمامية للوقوف. كرر على الجانبين.','squat'),
('glute-bridge','Glute bridge','رفع الحوض','Mat','حصيرة','Lie with feet flat and knees bent. Lift your hips, pause briefly, then lower slowly.','استلقِ مع ثني الركبتين ووضع القدمين على الأرض. ارفع الحوض، توقف قليلاً ثم انزل ببطء.','hinge'),
('overhead-press','Seated shoulder press','ضغط الكتف جلوساً','Dumbbells and bench','دمبل ومقعد','Sit tall with dumbbells at shoulder height. Press up in a comfortable range, then lower with control.','اجلس باعتدال والدمبل عند مستوى الكتفين. ادفعه للأعلى ضمن مدى مريح ثم أنزله بتحكم.','push'),
('dead-bug','Dead bug','تمرين الحشرة الميتة','Mat','حصيرة','Lie on your back with arms raised and knees bent. Slowly extend the opposite arm and leg, then alternate sides.','استلقِ على ظهرك مع رفع الذراعين وثني الركبتين. مد الذراع والساق المقابلة ببطء ثم بدّل الجانبين.','core');
