insert into public.plans(id,coach_id,title,draft) values('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Build your base','{"schema":1,"description":"Two full-body sessions built around simple, repeatable movements.","descriptionAr":"حصتان لكامل الجسم بحركات بسيطة وقابلة للتكرار.","days":[{"id":"foundation-a","name":"Full body A","nameAr":"كامل الجسم أ","minutes":35,"exercises":[{"key":"squat","exerciseId":"goblet-squat","sets":3,"reps":10,"load":8,"unit":"kg","rest":75,"note":""},{"key":"row","exerciseId":"dumbbell-row","sets":3,"reps":10,"load":8,"unit":"kg","rest":75,"note":""},{"key":"press","exerciseId":"floor-press","sets":3,"reps":10,"load":6,"unit":"kg","rest":75,"note":""},{"key":"hinge","exerciseId":"romanian-deadlift","sets":3,"reps":12,"load":8,"unit":"kg","rest":75,"note":""}]},{"id":"foundation-b","name":"Full body B","nameAr":"كامل الجسم ب","minutes":30,"exercises":[{"key":"split","exerciseId":"split-squat","sets":3,"reps":8,"load":0,"unit":"kg","rest":60,"note":""},{"key":"bridge","exerciseId":"glute-bridge","sets":3,"reps":12,"load":0,"unit":"kg","rest":60,"note":""},{"key":"shoulder","exerciseId":"overhead-press","sets":3,"reps":10,"load":4,"unit":"kg","rest":60,"note":""},{"key":"core","exerciseId":"dead-bug","sets":3,"reps":8,"load":0,"unit":"kg","rest":60,"note":""}]}]}'::jsonb);
